with target as(select * from public.works where id=any(array[]::bigint[]) or open_library_id=any(array['OL699576W','OL699580W','OL699588W','OL699589W','OL699597W','OL702807W','OL719932W','OL719940W','OL719949W','OL719953W','OL719957W']::text[]) or regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['eeneigenhuis','hetlieveleven','schoonschip19451984','terugkeer','zelfschrijverworden','heleneswarth','dehuismeester','devlieger','heteeuwigemoment','hetvromevolk','onderdekorenmaat']::text[]) or id in(select work_id from public.catalog_work_title_aliases where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['eeneigenhuis','hetlieveleven','schoonschip19451984','terugkeer','zelfschrijverworden','heleneswarth','dehuismeester','devlieger','heteeuwigemoment','hetvromevolk','onderdekorenmaat']::text[]))),a as(select * from public.authors where id in(select author_id from target) or open_library_id=any(array['OL55234A','OL55572A','OL57758A']::text[]) or regexp_replace(lower(normalize(name,NFD)),'[^a-z0-9]','','g')=any(array['gerardkornelisvanhetreve','gerardreve','jeroenbrouwers','maartenthart','martinhart']::text[])),e as(select * from public.editions where work_id in(select id from target) or open_library_edition_id=any(array['OL4043155M','OL5146184M','OL2946565M','OL3992098M','OL2284633M','OL2299362M','OL2281984M','OL85879M','OL3268164M','OL4834348M','OL1306981M']::text[]) or regexp_replace(coalesce(isbn_13,''),'[-[:space:]]','','g')=any(array['9789010025012','9789025305338','9789010050908','9789054291305','9789068900446','9789029507509','9789029519496','9789029521437','9789029518208','9789029518734','9789029520447']::text[])) select jsonb_build_object('project','qvplwejffhjvxaypmjut','checked_at',clock_timestamp(),'works',coalesce((select jsonb_agg(to_jsonb(t) order by id) from target t),'[]'),'authors',coalesce((select jsonb_agg(to_jsonb(t) order by id) from a t),'[]'),'author_corpora',coalesce((select jsonb_agg(to_jsonb(t) order by id) from public.works t where author_id in(select id from a)),'[]'),'editions',coalesce((select jsonb_agg(to_jsonb(t) order by id) from e t),'[]'),'metadata',coalesce((select jsonb_agg(to_jsonb(t) order by edition_id) from public.catalog_edition_metadata t where edition_id in(select id from e)),'[]'),'descriptions',coalesce((select jsonb_agg(to_jsonb(t) order by work_id,language) from public.catalog_work_descriptions t where work_id in(select id from target)),'[]'),'aliases',coalesce((select jsonb_agg(to_jsonb(t) order by work_id,title) from public.catalog_work_title_aliases t where work_id in(select id from target)),'[]')) as snapshot;
